    {
        Command = $"{CommandName} request",
        Outcome = "rendered",
        Repo = repo,
        Pr = pr,
        HeadSha = head,
        ExecutionUnit = unit,
        Runtime = runtime,
        Model = model,
        Effort = effort,
        OutDir = outDir,
        OpencodeProviderConfig = opencodeProviderConfig,
        Files = files,
        Invocation = invocation.TrimEnd('\n'),
